package com.processVisualisation.virtualKitchen.ai.provider.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

import lombok.Data;

/**
 * Binds configuration properties under the {@code ai.deepinfra} prefix,
 * including the API key, base URL, chat endpoint, default model and request
 * timeout used to call DeepInfra's OpenAI-compatible chat completions API.
 * Getters and setters are generated by Lombok's {@link Data} annotation.
 */
@Data
@Component
@ConfigurationProperties(prefix = "ai.deepinfra")
public class DeepInfraProperties {

    private String apiKey;
    private String baseUrl;
    private String chatEndpoint;
    private String defaultModel;
    private Long timeoutMs;

    /**
     * Sent as {@code reasoning_effort} when set (e.g. {@code none} to switch thinking off on reasoning models);
     * blank leaves the parameter out and the model's own default applies.
     */
    private String reasoningEffort;

    /**
     * When true, a request carrying a JSON Schema is sent as {@code response_format: json_schema}; when false it
     * degrades to plain JSON mode ({@code json_object}) and the backend's own validation enforces the shape.
     */
    private boolean jsonSchemaEnabled = true;
}
